// searchQueue builds a queue whose resolver answers only the given sources and
// whose FetchGate runs on the injectable clock (deterministic spacing slots).
func searchQueue(t *testing.T, srcs map[string]sdk.MetadataSource, clock func() time.Time) (*Queue, *store.Store) {
	t.Helper()
	s, reg := queueTestStore(t)
	q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
	q.resolve = mapResolver(srcs).resolver()
	if clock != nil {
		q.deps.FetchGate = newFetchGate(clock)
	}
	return q, s
}

// TestSearchSource covers the identify overlay's search passthrough (identify-
// match-override): served order verbatim with convention-field maps, and the
// error paths — the unsupported sentinel (direct and across a text round-trip
// seam), the manager's unknown-plugin error, and a failed fetch.
func TestSearchSource(t *testing.T) {
	ctx := context.Background()
	live := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_, _ = w.Write([]byte(`[]`))
	}))
	t.Cleanup(live.Close)

	full := &metadatav1.SearchCandidate{
		ExternalId: "378", Title: "Aria the Animation", Kind: "tv",
		RussianTitle: proto.String("Ария: Анимация"), Year: proto.Int32(2005),
		Episodes: proto.Int32(13), Poster: proto.String("https://shikimori.io/p.jpg"),
	}
	minimal := &metadatav1.SearchCandidate{ExternalId: "40709", Title: "Wake Up, Aria!", Kind: "ova"}

	cases := []struct {
		name     string
		srcs     map[string]sdk.MetadataSource
		checkErr func(t *testing.T, err error)
		want     []map[string]any
	}{
		{
			name: "order_and_fields_verbatim",
			srcs: map[string]sdk.MetadataSource{"shikimori": &searchSrc{
				spec:  &metadatav1.RequestSpec{Method: "GET", UrlTemplate: live.URL + "/search"},
				cands: []*metadatav1.SearchCandidate{full, minimal},
			}},
			want: []map[string]any{
				{"external_id": "378", "title": "Aria the Animation", "kind": "tv",
					"russian_title": "Ария: Анимация", "year": int32(2005), "episodes": int32(13),
					"poster": "https://shikimori.io/p.jpg"},
				{"external_id": "40709", "title": "Wake Up, Aria!", "kind": "ova"},
			},
		},
		{
			name: "unsupported_sentinel_direct",
			srcs: map[string]sdk.MetadataSource{"shikimori": &searchSrc{specErr: sdk.ErrSearchUnsupported}},
			checkErr: func(t *testing.T, err error) {
				if !errors.Is(err, sdk.ErrSearchUnsupported) {
					t.Fatalf("err = %v, want ErrSearchUnsupported (errors.Is)", err)
				}
			},
		},
		{
			name: "unsupported_sentinel_across_text_seam",
			srcs: map[string]sdk.MetadataSource{"shikimori": &searchSrc{
				specErr: errors.New(sdk.ErrSearchUnsupported.Error()), // a gRPC status round-trip
			}},
			checkErr: func(t *testing.T, err error) {
				if !errors.Is(err, sdk.ErrSearchUnsupported) {
					t.Fatalf("err = %v, want ErrSearchUnsupported re-wrapped from the seam text", err)
				}
			},
		},
		{
			name: "unknown_plugin_from_the_manager",
			srcs: map[string]sdk.MetadataSource{},
			checkErr: func(t *testing.T, err error) {
				if err == nil {
					t.Fatal("an unknown plugin must error from the manager")
				}
			},
		},
		{
			name: "failed_fetch_errors",
			srcs: map[string]sdk.MetadataSource{"shikimori": &searchSrc{
				spec: &metadatav1.RequestSpec{Method: "GET", UrlTemplate: "http://127.0.0.1:1/search"},
			}},
			checkErr: func(t *testing.T, err error) {
				if err == nil {
					t.Fatal("a failed fetch must error (the api maps it to the canonical upstream answer)")
				}
			},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			q, _ := searchQueue(t, tc.srcs, nil)
			cands, err := q.SearchSource(ctx, "shikimori", "aria", "")
			if tc.checkErr != nil {
				tc.checkErr(t, err)
				return
			}
			if err != nil {
				t.Fatalf("SearchSource: %v", err)
			}
			if !reflect.DeepEqual(cands, tc.want) {
				t.Fatalf("candidates = %v, want %v", cands, tc.want)
			}
		})
	}
}

// TestSearchSourceGateSpacing pins the budget share (identify-match-override):
// the interactive fetch lands on the SAME per-plugin slot the sweeps use — the
// second send for a plugin is spaced at least its spec's min_interval_ms after
// the first. The fixed clock books deterministic slots; the gate's wait is a
// real timer, so the second call completes and the slot shows the spacing.
func TestSearchSourceGateSpacing(t *testing.T) {
	ctx := context.Background()
	t0 := time.Date(2026, 10, 22, 9, 0, 0, 0, time.UTC)
	live := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_, _ = w.Write([]byte(`[]`))
	}))
	t.Cleanup(live.Close)

	q, _ := searchQueue(t, map[string]sdk.MetadataSource{"shikimori": &searchSrc{
		spec: &metadatav1.RequestSpec{Method: "GET", UrlTemplate: live.URL + "/search", MinIntervalMs: 700},
	}}, func() time.Time { return t0 })

	for i := 0; i < 2; i++ {
		if _, err := q.SearchSource(ctx, "shikimori", "aria", ""); err != nil {
			t.Fatalf("SearchSource #%d: %v", i+1, err)
		}
	}
	g := q.deps.FetchGate
	g.mu.Lock()
	last, seen := g.last["shikimori"]
	g.mu.Unlock()
	if !seen {
		t.Fatal("the interactive fetch never booked a gate slot")
	}
	if want := t0.Add(700 * time.Millisecond); !last.Equal(want) {
		t.Fatalf("gate slot = %v, want %v (the second send spaced a full interval after the first)", last, want)
	}
}

// identifySrc is the re-anchored shikimori stand-in for IdentifySeries: it
// captures every Match's existing_ids (the id-anchored re-derive proof) and
// writes a fresh namespace whose title is the picked candidate's.
type identifySrc struct {
	sdk.UnsupportedSearch // the interactive search pair: unsupported (identify-match-override)
	id                    string
	mu                    sync.Mutex
	seenIDs               []map[string]any
}

var _ sdk.MetadataSource = (*identifySrc)(nil)

func (s *identifySrc) Match(_ context.Context, req *metadatav1.MatchRequest) (*metadatav1.MatchResult, error) {
	s.mu.Lock()
	s.seenIDs = append(s.seenIDs, req.GetExistingIds().AsMap())
	s.mu.Unlock()
	return &metadatav1.MatchResult{Applies: true}, nil
}
func (s *identifySrc) BuildRequest(context.Context, *metadatav1.BuildRequestRequest) (*metadatav1.BuildRequestResponse, error) {
	return &metadatav1.BuildRequestResponse{}, nil
}
func (s *identifySrc) Convert(context.Context, *metadatav1.ConvertRequest) (*metadatav1.ConvertResult, error) {
	md, _ := structpb.NewStruct(map[string]any{"title": "Aria the Animation"})
	return &metadatav1.ConvertResult{Metadata: md}, nil
}
func (s *identifySrc) Merge(_ context.Context, req *metadatav1.MergeRequest) (*metadatav1.MergeResult, error) {
	return &metadatav1.MergeResult{Document: wrapNamespace(s.id, req.GetIncoming(), false)}, nil
}

func (s *identifySrc) lastExisting() map[string]any {
	s.mu.Lock()
	defer s.mu.Unlock()
	if len(s.seenIDs) == 0 {
		return nil
	}
	return s.seenIDs[len(s.seenIDs)-1]
}

// TestIdentifySeries is the identify action (identify-match-override): the
// anchor overwrite + id-anchored re-derive with byte-parity for the display
// name, the deferred no-write path, and the write-nothing error paths.
func TestIdentifySeries(t *testing.T) {
	ctx := context.Background()

	identifiedDoc := func() map[string]any {
		doc := serialDoc("Show.Name.S01")
		doc["sources"] = map[string]any{
			"serial-parser": map[string]any{"title": "Show Name", "season": int64(1)},
			"shikimori":     map[string]any{"title": map[string]any{"romaji": "WRONG"}, "score": 4.65},
		}
		return doc
	}

	t.Run("reanchor_and_id_anchored_rederive", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, err := s.CreateLibrary(ctx, "serial", filepath.Join(t.TempDir(), "lib"), "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		serID := putSeriesRow(t, s, "serial", libID, "Show.Name.S01", statusReady, identifiedDoc())
		src := &identifySrc{id: "shikimori"}
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{Backoff: time.Millisecond})
		q.resolve = mapResolver{"shikimori": src, "serial-parser": &succeedSrc{id: "serial-parser"}}.resolver()
		if err := q.Start(ctx); err != nil {
			t.Fatalf("Start: %v", err)
		}
		defer q.Stop()

		queued, stripped, deferred, err := q.IdentifySeries(ctx, serID, "shikimori", "378")
		if err != nil {
			t.Fatalf("IdentifySeries: %v", err)
		}
		if !queued || stripped != 1 || deferred != 0 {
			t.Fatalf("queued=%v stripped=%d deferred=%d, want true/1/0", queued, stripped, deferred)
		}

		sr := waitForSeriesStatus(t, s, serID, statusReady, 2*time.Second)
		d := decodeDoc(sr.Document)
		ids, _ := d["identifiers"].(map[string]any)
		// decoded from the persisted JSON, the numeric anchor reads back float64
		if ids["shikimori_id"] != float64(378) {
			t.Fatalf("identifiers.shikimori_id = %v (%T), want 378 (numeric anchor)", ids["shikimori_id"], ids["shikimori_id"])
		}
		seen := src.lastExisting()
		if seen == nil || seen["shikimori_id"] != float64(378) {
			t.Fatalf("the re-derive's Match saw existing_ids %v, want the picked anchor 378", seen)
		}
		fresh, _ := d["sources"].(map[string]any)["shikimori"].(map[string]any)
		if fresh["title"] != "Aria the Animation" {
			t.Fatalf("shikimori namespace not rebuilt from the picked id: %v", fresh)
		}
		parser, _ := d["sources"].(map[string]any)["serial-parser"]
		if !reflect.DeepEqual(parser, map[string]any{"title": "Show Name", "season": float64(1)}) {
			t.Fatalf("the display-name namespace moved during identify: %v", parser)
		}
	})

	t.Run("held_lease_defers_with_no_write", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, err := s.CreateLibrary(ctx, "serial", filepath.Join(t.TempDir(), "lib"), "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		serID := putSeriesRow(t, s, "serial", libID, "Show.Name.S01", statusReady, identifiedDoc())
		before, err := s.GetSeries(ctx, serID)
		if err != nil {
			t.Fatalf("GetSeries: %v", err)
		}
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
		if !q.leases.acquire(serID, "worker", time.Minute) {
			t.Fatal("precondition: acquiring the live lease failed")
		}
		queued, stripped, deferred, err := q.IdentifySeries(ctx, serID, "shikimori", "378")
		if err != nil {
			t.Fatalf("IdentifySeries: %v", err)
		}
		if queued || stripped != 0 || deferred != 1 {
			t.Fatalf("queued=%v stripped=%d deferred=%d, want false/0/1", queued, stripped, deferred)
		}
		after, err := s.GetSeries(ctx, serID)
		if err != nil {
			t.Fatalf("GetSeries after: %v", err)
		}
		if string(before.Document) != string(after.Document) {
			t.Fatalf("a lease-held row must stay byte-identical:\nbefore %s\nafter  %s", before.Document, after.Document)
		}
	})

	t.Run("write_nothing_error_paths", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, err := s.CreateLibrary(ctx, "serial", filepath.Join(t.TempDir(), "lib"), "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		serID := putSeriesRow(t, s, "serial", libID, "Show.Name.S01", statusReady, identifiedDoc())
		before, err := s.GetSeries(ctx, serID)
		if err != nil {
			t.Fatalf("GetSeries: %v", err)
		}
		// shikimori IS loaded here so the unknown_series case really exercises
		// the series lookup, not the plugin resolution.
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
		q.resolve = mapResolver{"shikimori": &identifySrc{id: "shikimori"}}.resolver()

		cases := []struct {
			name       string
			seriesID   string
			pluginID   string
			externalID string
			wantErr    error
		}{
			{"unknown_series", "ser_missing", "shikimori", "378", nil},
			{"unknown_plugin", serID, "kinopoisk", "42", nil},
			{"empty_external_id", serID, "shikimori", "", errEmptyExternalID},
		}
		for _, tc := range cases {
			t.Run(tc.name, func(t *testing.T) {
				_, _, _, err := q.IdentifySeries(ctx, tc.seriesID, tc.pluginID, tc.externalID)
				if err == nil {
					t.Fatalf("%s must error", tc.name)
				}
				if tc.wantErr != nil && !errors.Is(err, tc.wantErr) {
					t.Fatalf("%s err = %v, want %v", tc.name, err, tc.wantErr)
				}
				after, gerr := s.GetSeries(ctx, serID)
				if gerr != nil {
					t.Fatalf("GetSeries after: %v", gerr)
				}
				if string(before.Document) != string(after.Document) {
					t.Fatalf("%s must write nothing:\nbefore %s\nafter  %s", tc.name, before.Document, after.Document)
				}
			})
		}
	})
}

// deadSearchSpec is a GET spec against an address that refuses connections —
// the canonical NETWORK-class search fetch failure (no response ever arrives).
func deadSearchSpec() *metadatav1.RequestSpec {
	return &metadatav1.RequestSpec{Method: "GET", UrlTemplate: "http://127.0.0.1:1/search"}
}

func deadSearchSrc() *searchSrc {
	return &searchSrc{spec: deadSearchSpec()}
}

// relaySearchSrc captures the SearchResults request so a test can prove the
// STORED relay response (not a server fetch) fed the conversion.
type relaySearchSrc struct {
	searchSrc
	mu   sync.Mutex
	last *metadatav1.SearchResultsRequest
}

func (s *relaySearchSrc) SearchResults(ctx context.Context, req *metadatav1.SearchResultsRequest) (*metadatav1.SearchResultsResult, error) {
	s.mu.Lock()
	s.last = req
	s.mu.Unlock()
	return s.searchSrc.SearchResults(ctx, req)
}

func (s *relaySearchSrc) fetched() *metadatav1.SearchResultsRequest {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.last
}

// claimAndIngest plays the client side of the relay for one search job: spin
// (real-time backstop — the poll and the enrich fake clock are the timed
// parties) until the enqueue lands, claim through the SAME Relay.Claim the api
// pair serves, and Ingest the scripted outcome. Asserts the job's search
// identity on the way through. stop ends the spin without a failed-test report
// (the test's Cleanup closes it so an early test exit never leaves a
// goroutine reporting into a finished test).
func claimAndIngest(t *testing.T, r *Relay, result relay.RelayResult, stop <-chan struct{}) {
	t.Helper()
	deadline := time.Now().Add(2 * time.Second)
	for {
		job, found, err := r.Claim(context.Background(), "test-principal")
		if err != nil {
			t.Errorf("relay claim: %v", err)
			return
		}
		if found {
			if job.Purpose != relayPurposeSearch || job.RowID != "" || job.PluginID != "shikimori" {
				t.Errorf("search job identity: purpose=%q row=%q plugin=%q", job.Purpose, job.RowID, job.PluginID)
				return
			}
			if err := r.Ingest(context.Background(), job.ID, "test-principal", result); err != nil {
				t.Errorf("relay ingest: %v", err)
			}
			return
		}
		select {
		case <-stop:
			return
		case <-time.After(2 * time.Millisecond):
		}
		if time.Now().After(deadline) {
			t.Error("the search job never became claimable")
			return
		}
	}
}

// stepClock installs a fake package clock that advances one step per read and
// returns a reader for the current fake time. The stepper keeps the poll's
// budget finite under a regression (a broken hold fails in seconds, never
// hangs), and the readback turns the budget into an assertion. Both closures
// are mutex-guarded: the client-side goroutines read the clock concurrently
// with the test goroutine's readback.
func stepClock(t *testing.T, start time.Time, step time.Duration) (read func() time.Time) {
	t.Helper()
	realNow := now
	t.Cleanup(func() { now = realNow })
	mu := &sync.Mutex{}
	cur := start
	now = func() time.Time {
		mu.Lock()
		defer mu.Unlock()
		cur = cur.Add(step)
		return cur
	}
	return func() time.Time {
		mu.Lock()
		defer mu.Unlock()
		return cur
	}
}

// TestSearchRelayCompletes pins the completion leg of the search relay (ruled
// OQ-6): the server fetch fails network-class, the job enqueues (purpose
// search, no row — and no ledger row), the client side claims and Ingests a
// done result through the same Claim→Ingest round trip enrich jobs ride, and
// the held closure answers the candidates converted from the STORED response —
// within the budget (asserted off the fake clock's readback). A done job's
// stored response feeds SearchResults whatever status it carries (the direct
// path's contract), and the fed result is consumed (D4's read-that-fed
// discipline).
func TestSearchRelayCompletes(t *testing.T) {
	ctx := context.Background()
	t0 := time.Date(2026, 10, 22, 9, 0, 0, 0, time.UTC)
	clock := stepClock(t, t0, time.Second) // 1s per read: the budget passes in a minute of reads — the done job answers in a few

	cases := []struct {
		name   string
		body   string
		status int
		cands  []*metadatav1.SearchCandidate
		want   []map[string]any
	}{
		{
			name:   "done_response_feeds_searchresults",
			body:   `[]`,
			status: 200,
			cands: []*metadatav1.SearchCandidate{
				{ExternalId: "378", Title: "Aria the Animation", Kind: "tv", Year: proto.Int32(2005)},
			},
			want: []map[string]any{
				{"external_id": "378", "title": "Aria the Animation", "kind": "tv", "year": int32(2005)},
			},
		},
		{
			name:   "any_stored_status_feeds_like_the_direct_path",
			body:   `{"message":"rate limited"}`,
			status: 502,
			cands: []*metadatav1.SearchCandidate{
				{ExternalId: "40709", Title: "Wake Up, Aria!", Kind: "ova"},
			},
			want: []map[string]any{
				{"external_id": "40709", "title": "Wake Up, Aria!", "kind": "ova"},
			},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			src := &relaySearchSrc{searchSrc: searchSrc{spec: deadSearchSpec(), cands: tc.cands}}
			q, s := searchQueue(t, map[string]sdk.MetadataSource{"shikimori": src}, nil)
			r := &Relay{Store: s}
			q.deps.Relay = r

			stop := make(chan struct{})
			t.Cleanup(func() { close(stop) })
			go claimAndIngest(t, r, relay.RelayResult{
				HTTPStatus: tc.status,
				Headers:    map[string]string{"Content-Type": "application/json"},
				Body:       []byte(tc.body),
			}, stop)

			cands, err := q.SearchSource(ctx, "shikimori", "aria", "")
			if err != nil {
				t.Fatalf("SearchSource over the relay: %v", err)
			}
			if !clock().Before(t0.Add(relaySearchBudget)) {
				t.Fatalf("the answer came at %v past t0 — the budget, not the done job", clock().Sub(t0))
			}
			if !reflect.DeepEqual(cands, tc.want) {
				t.Fatalf("candidates = %v, want %v", cands, tc.want)
			}
			f := src.fetched()
			if f == nil {
				t.Fatal("SearchResults never ran")
			}
			fe := f.GetFetched()
			if !fe.GetFetched() || fe.GetHttpStatus() != int32(tc.status) || string(fe.GetBody()) != tc.body {
				t.Fatalf("SearchResults fed %v, want the stored response (status %d, body %q, fetched)", fe, tc.status, tc.body)
			}
			if f.GetQuery() != "aria" || f.GetKind() != "" {
				t.Fatalf("SearchResults query/kind = %q/%q, want aria/\"\"", f.GetQuery(), f.GetKind())
			}
			rows, err := s.ListFailures(ctx)
			if err != nil {
				t.Fatalf("ListFailures: %v", err)
			}
			if len(rows) != 0 {
				t.Fatalf("a search job must write no ledger row, found %d", len(rows))
			}
			var consumed int
			if err := s.DB().QueryRowContext(ctx, `SELECT consumed FROM relay_jobs WHERE purpose = 'search'`).Scan(&consumed); err != nil {
				t.Fatalf("relay job read: %v", err)
			}
			if consumed != 1 {
				t.Fatalf("the fed result was not consumed: consumed=%d", consumed)
			}
		})
	}
}

// TestSearchRelayExpiresToUpstreamError pins the give-up legs (ruled OQ-6): a
// job the client never completes — never claimed with the budget spent out,
// claimed-then-failed, or claimed-then-abandoned past its lease — answers the
// SAME upstream error the endpoint answers today with retry disabled:
// byte-for-byte the immediate answer a relay-disabled queue gives for the same
// failing fetch. The fake clock drives the budget so the suite stays fast.
func TestSearchRelayExpiresToUpstreamError(t *testing.T) {
	ctx := context.Background()
	t0 := time.Date(2026, 10, 22, 9, 0, 0, 0, time.UTC)
	realNow := now
	t.Cleanup(func() { now = realNow })

	// The immediate answer today: a relay-disabled queue for the same failing
	// fetch. The endpoint writes err.Error() verbatim into its 502 with retry
	// disabled — every give-up below must reproduce it byte-for-byte.
	qNow, _ := searchQueue(t, map[string]sdk.MetadataSource{"shikimori": deadSearchSrc()}, nil)
	_, wantErr := qNow.SearchSource(ctx, "shikimori", "aria", "")
	if wantErr == nil || !strings.HasPrefix(wantErr.Error(), "enrich: search fetch: ") {
		t.Fatalf("baseline immediate answer = %v", wantErr)
	}

	assertUpstream := func(t *testing.T, err error) {
		t.Helper()
		if err == nil || err.Error() != wantErr.Error() {
			t.Fatalf("give-up answer = %v, want byte-identical %v", err, wantErr)
		}
	}

	t.Run("unclaimed_budget_expires", func(t *testing.T) {
		// An advancing fake clock: the 60 s budget spends out in two reads —
		// no real waiting; no client ever claims the job. The readback proves
		// the budget WAS what spent out.
		clock := stepClock(t, t0, 31*time.Second)
		q, s := searchQueue(t, map[string]sdk.MetadataSource{"shikimori": deadSearchSrc()}, nil)
		q.deps.Relay = &Relay{Store: s}
		_, err := q.SearchSource(ctx, "shikimori", "aria", "")
		assertUpstream(t, err)
		if !clock().After(t0.Add(relaySearchBudget)) {
			t.Fatalf("answered at %v past t0 — the budget never spent out", clock().Sub(t0))
		}
	})

	t.Run("failed_job_answers_upstream", func(t *testing.T) {
		// A slow-stepping clock: the budget CANNOT be what answers (asserted
		// off the readback — the FAILED state must be) — the client executes
		// but reports a transport failure (Ingest's error set) through the
		// same round trip.
		clock := stepClock(t, t0, time.Second)
		q, s := searchQueue(t, map[string]sdk.MetadataSource{"shikimori": deadSearchSrc()}, nil)
		r := &Relay{Store: s}
		q.deps.Relay = r
		stop := make(chan struct{})
		t.Cleanup(func() { close(stop) })
		go claimAndIngest(t, r, relay.RelayResult{Error: "the client could not reach the upstream either"}, stop)
		_, err := q.SearchSource(ctx, "shikimori", "aria", "")
		assertUpstream(t, err)
		if clock().After(t0.Add(relaySearchBudget)) {
			t.Fatalf("answered at %v past t0 — the budget, not the failed job", clock().Sub(t0))
		}
		rows, err := s.ListFailures(ctx)
		if err != nil {
			t.Fatalf("ListFailures: %v", err)
		}
		if len(rows) != 0 {
			t.Fatalf("a failed search round must touch no ledger row, found %d", len(rows))
		}
	})

	t.Run("expired_claim_answers_upstream", func(t *testing.T) {
		// The clock is pinned until the claim lands, then jumps an hour: the
		// poll reads the abandoned lease as expired (the lazy expiry, D3) —
		// the lease is handed out at 1µs so any later read sees it past. The
		// search runs concurrently with the claimant: the job must exist
		// before a claim can land.
		mu := &sync.Mutex{}
		released := false
		now = func() time.Time {
			mu.Lock()
			defer mu.Unlock()
			if released {
				return t0.Add(time.Hour)
			}
			return t0
		}
		q, s := searchQueue(t, map[string]sdk.MetadataSource{"shikimori": deadSearchSrc()}, nil)
		r := &Relay{Store: s, LeaseTTL: time.Microsecond}
		q.deps.Relay = r
		type searchOutcome struct {
			err error
		}
		out := make(chan searchOutcome, 1)
		go func() {
			_, err := q.SearchSource(ctx, "shikimori", "aria", "")
			out <- searchOutcome{err: err}
		}()
		claimed := make(chan struct{})
		go func() {
			deadline := time.Now().Add(2 * time.Second)
			for {
				_, found, err := r.Claim(context.Background(), "test-principal")
				if err != nil {
					t.Errorf("relay claim: %v", err)
					return
				}
				if found { // claimed, never ingested — the claimant abandons
					close(claimed)
					return
				}
				if time.Now().After(deadline) {
					t.Error("the search job never became claimable")
					return
				}
				time.Sleep(2 * time.Millisecond)
			}
		}()
		<-claimed
		mu.Lock()
		released = true
		mu.Unlock()
		o := <-out
		assertUpstream(t, o.err)
	})
}

// TestSearchRelayNonNetworkUnchanged pins the class gate (ruled OQ-6): the
// relay is the NETWORK-class path only — every other search failure keeps
// today's immediate answer, even with the relay live (a fast-spending fake
// clock turns a wrongly-relayed hold into a fast give-up, and the zero-jobs
// assertion catches the detour).
func TestSearchRelayNonNetworkUnchanged(t *testing.T) {
	ctx := context.Background()
	t0 := time.Date(2026, 10, 22, 9, 0, 0, 0, time.UTC)
	realNow := now
	t.Cleanup(func() { now = realNow })
	step := t0
	now = func() time.Time { step = step.Add(time.Minute); return step }

	live := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_, _ = w.Write([]byte(`[]`))
	}))
	t.Cleanup(live.Close)

	cases := []struct {
		name     string
		src      *searchSrc
		checkErr func(t *testing.T, err error)
	}{
		{
			name: "unsupported_search_sentinel",
			src:  &searchSrc{specErr: sdk.ErrSearchUnsupported},
			checkErr: func(t *testing.T, err error) {
				if !errors.Is(err, sdk.ErrSearchUnsupported) {
					t.Fatalf("err = %v, want ErrSearchUnsupported", err)
				}
			},
		},
		{
			name: "specs_rpc_failure",
			src:  &searchSrc{specErr: errors.New("specs rpc boom")},
			checkErr: func(t *testing.T, err error) {
				if err == nil || err.Error() != "enrich: search: specs rpc boom" {
					t.Fatalf("err = %v, want today's immediate wrap", err)
				}
			},
		},
		{
			name: "spec_class_method_rejected_before_any_fetch",
			src:  &searchSrc{spec: &metadatav1.RequestSpec{Method: "DELETE", UrlTemplate: live.URL + "/search"}},
			checkErr: func(t *testing.T, err error) {
				if err == nil || !strings.HasPrefix(err.Error(), "enrich: search fetch: unsupported method") {
					t.Fatalf("err = %v, want today's immediate spec-class answer", err)
				}
			},
		},
		{
			name: "spec_class_unresolved_placeholder",
			src:  &searchSrc{spec: &metadatav1.RequestSpec{Method: "GET", UrlTemplate: live.URL + "/search?q={query}"}},
			checkErr: func(t *testing.T, err error) {
				if err == nil || !strings.HasPrefix(err.Error(), "enrich: search fetch: placeholder") {
					t.Fatalf("err = %v, want today's immediate spec-class answer", err)
				}
			},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			q, s := searchQueue(t, map[string]sdk.MetadataSource{"shikimori": tc.src}, nil)
			q.deps.Relay = &Relay{Store: s} // live: the non-network path must ignore it
			_, err := q.SearchSource(ctx, "shikimori", "aria", "")
			tc.checkErr(t, err)
			if _, found := relayClaim(t, s); found {
				t.Fatal("a non-network failure must not enqueue a relay job")
			}
		})
	}
}
